              id: node.id,
              label: node.label,
              title: node.title,
              color: {
                  background: '#48bb78',
                  border: '#38a169',
                  highlight: {
                      background: '#68d391',
                      border: '#38a169'
                  }
              },
              font: {
                  color: 'white',
                  size: 14,
                  face: 'Arial'
              },
